const scenarios = [
 {id:'normal',title:'Normal delivery',subtitle:'Establish the baseline',position:'relay',surface:'none',actor:'No attacker',about:'Alex sends a meeting time. Blair should receive exactly the same message.',attack:'There is no attacker in this baseline. The relay forwards the message unchanged.',defense:'tls',control:'TLS transport',before:'Original message delivered',after:'Original message delivered',takeaway:'A normal relay preserves the message. Next, introduce an observer to see what can go wrong.',action:'forward'},
 {id:'listen',title:'Network listening',subtitle:'Can someone read the message?',position:'network',surface:'nodeNetwork',actor:'On-path observer',about:'An observer sits between Alex and the relay and tries to read the message in transit.',attack:'Attack starts HERE: on the network link, before the message reaches the relay. The observer inspects the payload.',defense:'tls',control:'TLS transport',before:'Message exposed to observer',after:'Observer sees only ciphertext',takeaway:'TLS conceals the message from an on-path observer. It does not conceal plaintext from the application relay that terminates TLS.',action:'view'},
 {id:'tamper',title:'Relay tampering',subtitle:'Can someone change the message?',position:'relay',surface:'nodeRelay',actor:'Compromised relay',about:'A relay insider changes the meeting time after transport encryption has ended.',attack:'Attack starts HERE: inside the application relay. The attacker replaces “library at 3 PM” with “station at 9 PM”.',defense:'integrity',control:'End-to-end integrity',before:'Blair accepts the altered message',after:'Blair rejects the altered message',takeaway:'TLS alone does not stop a malicious relay. End-to-end integrity detects the change at the recipient; it does not hide the content.',action:'edit'},
 {id:'identity',title:'Sender impersonation',subtitle:'Who is allowed to send?',position:'anonymous',surface:'nodeSender',actor:'Unauthenticated impostor',about:'An impostor claims to be Alex without presenting a valid credential.',attack:'Attack starts HERE: at the sender identity gate. The synthetic impostor tries to enter as Alex.',defense:'auth',control:'Authentication',before:'Impostor admitted without credentials',after:'Impostor rejected before delivery',takeaway:'Authentication checks who may enter the conversation. A display name alone is not a verified identity.',action:'admission'},
 {id:'origin',title:'Foreign website',subtitle:'Where did the request start?',position:'cross-origin',surface:'nodeRelay',actor:'Untrusted website',about:'A browser connection comes from an unapproved website and attempts to use the messaging service.',attack:'Attack starts HERE: at the relay connection gate. A synthetic foreign website attempts an unauthorized connection.',defense:'origin',control:'Origin validation',before:'Foreign website admitted',after:'Foreign website rejected',takeaway:'An origin allowlist restricts browser websites that may connect. It is a separate check from authentication, and is not a substitute for it.',action:'admission'},
 {id:'drop',title:'Message dropping',subtitle:'Can delivery be guaranteed?',position:'network',surface:'nodeNetwork',actor:'On-path disruptor',about:'An attacker prevents the message from reaching Blair instead of reading or changing it.',attack:'Attack starts HERE: on the network route. The attacker discards the synthetic message completely.',defense:'all',control:'All four defenses',before:'Message never arrives',after:'Message still never arrives',takeaway:'TLS, authentication, origin checks and integrity do not guarantee availability. Timeouts and resilient delivery need separate design.',action:'drop'}
];
const labels=['Briefing','Sender ready','Attack / baseline','First outcome','Enable defense','Replay protected','Compare'];
const text='Meet at the library at 3 PM.', changed='Meet at the station at 9 PM.';
const $=s=>document.querySelector(s);
export function installTour(api){
 let selected=0,step=0,running=false,all=false,timer=null,version=0,stepping=false,manual=false,completed=false;
 let first=null,second=null,hasStarted=false;
 const initialMode=()=>{manual=false;document.body.classList.add('guided-mode');$('#returnTour').hidden=true;$('#takeControl').hidden=false;$('#tourStory').hidden=false;$('#manualBanner').hidden=true;$('#defenseCaption').textContent='MODELED DEFENSES · THE TOUR CHANGES THESE FOR YOU';lock()};
 function lock(){if(manual)return;for(const k in api.config)$('#'+k).disabled=true;for(const f of ['A','B'])$('#form'+f).querySelector('button').disabled=true;}
 function stop(){running=false;clearTimeout(timer);timer=null;$('#tourPause').disabled=true;$('#tourPause').textContent='Pause';}
 function invalidate(){version++;stepping=false;stop();$('#tourNext').disabled=false;}
 function discardPending(){api.abortInFlight();const m=api.pending();if(m){api.release();api.finish(m,'failed','Operator ended the paused scenario before delivery.');}}
 function settings(protectedRun){for(const k in api.config){api.config[k]=false;$('#'+k).checked=false;}const s=scenarios[selected];if(protectedRun){if(s.defense==='all')for(const k in api.config)api.config[k]=true;else api.config[s.defense]=true;
 // Keep TLS on across both relay-tampering runs to isolate integrity's additional protection.
 }if(s.id==='tamper')api.config.tls=true;for(const k in api.config)$('#'+k).checked=api.config[k];$('#threat').value=s.position;$('#intercept').checked=!['normal','identity','origin'].includes(s.id);api.updateThreat();lock();}
 function surface(active,defended=false){const s=scenarios[selected];for(const node of document.querySelectorAll('.route-node'))node.classList.remove('attacker-here','defender-here');$('.interceptor').classList.toggle('attack-active',active&&s.id!=='normal');if(active&&s.surface!=='none')$('#'+s.surface).classList.add(defended?'defender-here':'attacker-here');$('#attackLocation').classList.toggle('active',active&&s.id!=='normal');$('#attackLocation').textContent=active?(s.id==='normal'?'BASELINE · No attack: the original message is forwarded.':(defended?'DEFENSE CHECK · ':'ATTACK STARTS HERE · ')+s.attack.replace('Attack starts HERE: ','')):'No attack in progress · '+s.about;$('#actorBadge').textContent=active&&s.id!=='normal'?(defended?'DEFENSE CHECK':'ATTACKER ACTIVE'):'SCENARIO OVERVIEW';$('#actorTitle').textContent=s.actor;$('#actorDescription').textContent=active?s.attack:s.about;}
 function draw(){const s=scenarios[selected];for(const [i,b]of [...$('#scenarios').children].entries()){b.setAttribute('aria-pressed',String(i===selected));b.classList.toggle('selected',i===selected)}$('#storyPosition').textContent=`SCENARIO ${selected+1} / ${scenarios.length} · ${s.title.toUpperCase()}`;$('#storySteps').replaceChildren();for(let i=0;i<labels.length;i++){const li=document.createElement('li');li.textContent=`${i+1}. ${labels[i]}`;li.className=i===step?'current':i<step?'done':'';if(i===step)li.setAttribute('aria-current','step');$('#storySteps').append(li)}$('#storyProgress').style.width=(step+1)/labels.length*100+'%';$('#storyState').textContent=completed?'TOUR COMPLETE':running?'AUTO PLAYING':step?'PAUSED / STEP MODE':'READY TO WATCH';$('#tourPause').disabled=!running&&(completed||!hasStarted);$('#tourPause').textContent=running?'Pause':'Resume';$('#tourNext').disabled=stepping;}
 function narrate(title,body,phase,verdict){$('#storyTitle').textContent=title;$('#storyText').textContent=body;$('#storyPhase').textContent=phase;$('#storyVerdict').textContent=verdict;draw();}
 function overview(){const s=scenarios[selected];first=null;second=null;completed=false;step=0;settings(false);surface(false);$('#originalPayload').textContent=text;$('#receivedPayload').textContent='Waiting for delivery…';$('#attackerPayload').textContent='No attack in progress.';$('#receivedLabel').textContent='RECIPIENT VIEW';narrate(s.title,s.about,'START HERE','Watch the unprotected and protected comparison.');$('#tourStatus').textContent='Choose Play all for the whole tour, Play this scenario for one story, or Next step to move at your own pace.';}
 async function waitResult(m,token){if(!m)throw Error('Connection is not ready.');const start=Date.now();while(!m.status){if(token!==version)return null;if(Date.now()-start>6000)throw Error('No relay acknowledgement. Reconnect and replay this scenario.');await new Promise(r=>setTimeout(r,30))}return m;}
 async function attempt(protectedRun,token){const s=scenarios[selected];api.setTourRun(protectedRun?'DEFENSE ON':'FIRST RUN');settings(protectedRun);$('#attackerPayload').textContent=s.action==='view'?(protectedRun?'[TLS ciphertext — message cannot be read]':text):s.action==='edit'?changed:s.action==='drop'?'Discard message; deliver nothing.':s.action==='admission'?(s.id==='identity'?'Claim: Alex · credential: missing':'Origin: https://foreign.invalid'):'None — normal forwarding.';$('#inputA').value=text;const m=api.send('A');if(!m)throw Error('Connection is not ready.');if(api.pending()){
   if(s.action==='edit')$('#edit').value=changed;
   if(s.action==='view'){api.act('view');api.act('forward');}else api.act(s.action==='admission'?'forward':s.action);
 }lock();const result=await waitResult(m,token);if(!result||token!==version)return null;if(result.status==='failed')throw Error(result.reason);
 const received=result.status==='delivered'?(result.changed?changed:text):result.status==='blocked'?'Rejected — not delivered to Blair.':result.status==='dropped'?'No message arrived.':'Transport failed.';
 $('#receivedPayload').textContent=received;$('#receivedPayload').classList.toggle('altered',Boolean(result.changed&&result.status==='delivered'));$('#receivedLabel').textContent=protectedRun?'RECIPIENT VIEW · DEFENSE ENABLED':'RECIPIENT VIEW · FIRST RUN';return result;
 }
 async function perform(next){if(stepping)return;stepping=true;step=next;draw();const token=version,s=scenarios[selected];try{
 if(step===0){overview();}
 if(step===1){surface(false);narrate('Alex prepares a message',`The intended message is “${text}” Blair should receive these exact words. ${s.id==='tamper'?'TLS is already enabled in both runs; watch what happens inside the relay.':'The first run leaves the relevant defense off.'}`,'SENDER READY','No attack has happened yet.');$('#originalPayload').textContent=text;$('#receivedPayload').textContent='Waiting for delivery…';}
 if(step===2){surface(true);narrate(s.id==='normal'?'The relay forwards the message':'Now the attacker intervenes',s.attack,s.id==='normal'?'NORMAL DELIVERY':'ATTACK IN PROGRESS',s.id==='normal'?'Alex → relay → Blair':`${s.actor} · ${s.position}`);first=await attempt(false,token);}
 if(token!==version)return;
 if(step===3){surface(true);narrate('What happened in the first run?',first?.status==='failed'?'The actual transport failed; replay when connected.':s.id==='normal'?'Blair receives the exact message Alex sent. This is the reference behavior for the remaining experiments.':s.before+'. '+(first?.reason||''),'FIRST OUTCOME',s.before);}
 if(step===4){surface(false);settings(true);narrate(`Enable ${s.control}`,s.id==='drop'?'All four modeled defenses are on. Try dropping the message again: these controls protect different properties, but none can force a network to deliver.':s.id==='normal'?'Turn on modeled TLS and send the same legitimate message again. Secure transport should still allow normal conversation.':`The tour enables ${s.control.toLowerCase()} and repeats exactly the same attempt. Watch the highlighted defense cards below.`,'DEFENSE ENABLED',s.control);}
 if(step===5){surface(true,true);narrate('Replay with the defense enabled',s.id==='drop'?'The disruptor drops the message again. The receiver still has nothing to read.':`The same ${s.id==='normal'?'normal delivery':'attack'} is repeated. Watch whether the recipient accepts it with the modeled defense enabled.`,'PROTECTED REPLAY',s.after);second=await attempt(true,token);}
 if(token!==version)return;
 if(step===6){surface(true,true);narrate('Compare the two outcomes',s.takeaway,'WHAT YOU LEARNED',`${s.before} → ${s.after}`);$('#tourStatus').textContent=all&&selected<scenarios.length-1?'This scenario is complete. Auto play continues to the next story.':'Scenario complete. Replay it, choose another story, or Take control to experiment yourself.';}
 }catch(e){stop();$('#storyState').textContent='CONNECTION NEEDED';$('#tourStatus').textContent=e.message;eventNote(e.message);}
 finally{if(token===version){stepping=false;draw();schedule();}}
 }
 function eventNote(message){api.event('tour',message)}
 function schedule(){clearTimeout(timer);if(running)timer=setTimeout(advance,3200/Number($('#tourSpeed').value));}
 async function advance(){if(stepping)return;if(step<6){await perform(step+1);return}if(all&&selected<scenarios.length-1){selected++;clearScene();overview();draw();schedule();}else{stop();completed=true;draw();$('#tourStatus').textContent=all?'All six stories complete. Take control to try your own message, attacker position and defenses.':'Story complete. Try another scenario, or Take control to experiment.';eventNote(all?'All six guided scenarios completed':'Guided scenario completed');}}
 function clearScene(){discardPending();for(const who of ['A','B'])$('#messages'+who).replaceChildren();$('#receivedPayload').classList.remove('altered');}
 function select(i){invalidate();hasStarted=false;discardPending();initialMode();selected=i;clearScene();overview();}
 function play(playAll){invalidate();hasStarted=true;discardPending();initialMode();if(playAll)selected=0;all=playAll;clearScene();overview();running=true;$('#tourStatus').textContent=playAll?'Auto play runs all six scenarios, including both comparisons. You can pause or take control at any time.':'Auto play runs this complete scenario, including the defense comparison.';draw();eventNote(playAll?'Started full guided tour':'Started '+scenarios[selected].title);schedule();}
 function manualSurface(){if(!manual)return;const mapping={network:'nodeNetwork',relay:'nodeRelay',anonymous:'nodeSender','cross-origin':'nodeRelay'},threat=$('#threat').value;for(const n of document.querySelectorAll('.route-node'))n.classList.remove('attacker-here','defender-here');$('#'+mapping[threat]).classList.add('attacker-here');$('#attackLocation').textContent='SELECTED ATTACK SURFACE · '+$('#threat').selectedOptions[0].textContent+'. Send a synthetic message to begin; inspect, edit or drop is the attack action.';$('#attackLocation').classList.add('active')}
 function takeControl(){invalidate();manual=true;api.setTourRun('');document.body.classList.remove('guided-mode');$('#returnTour').hidden=false;$('#takeControl').hidden=true;$('#tourStory').hidden=true;$('#manualBanner').hidden=false;$('#defenseCaption').textContent='YOUR DEFENSE SETTINGS · CHANGE THEM BEFORE SENDING';discardPending();api.syncBusy();$('.interceptor').classList.remove('attack-active');$('#intercept').checked=true;manualSurface();eventNote('Visitor took control of the sandbox');}
 for(const [i,s]of scenarios.entries()){const b=document.createElement('button');b.className='scenario-card';b.setAttribute('aria-pressed',String(i===selected));const n=document.createElement('span');n.textContent=`0${i+1}`;const strong=document.createElement('strong');strong.textContent=s.title;const small=document.createElement('small');small.textContent=s.subtitle;b.append(n,strong,small);b.onclick=()=>select(i);$('#scenarios').append(b)}
 $('#playAll').onclick=()=>play(true);$('#playScene').onclick=()=>play(false);$('#tourPause').onclick=()=>{if(running){stop();$('#tourStatus').textContent='Paused. Resume to continue automatically, or use Next step.';}else{running=true;$('#tourStatus').textContent='Auto play resumed.';schedule()}draw()};$('#tourNext').onclick=()=>{stop();hasStarted=true;completed=false;advance()};$('#tourSpeed').onchange=schedule;$('#takeControl').onclick=takeControl;$('#returnTour').onclick=()=>select(selected);
 $('#guided').onclick=()=>{play(true);$('#workspace').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
 $('#secure').addEventListener('click',()=>{if(!manual)takeControl()},{capture:true});
 $('#reset').addEventListener('click',()=>{invalidate();hasStarted=false;all=false;discardPending();if(!manual)overview()},{capture:true});
 $('#threat').addEventListener('change',manualSurface);
 for(const id of ['view','tamper','drop'])$('#'+id).addEventListener('click',()=>{if(manual){$('#attackLocation').textContent='ATTACK ACTION · '+$('#'+id).textContent+' at '+$('#threat').selectedOptions[0].textContent;$('.interceptor').classList.add('attack-active')}},{capture:true});
 initialMode();overview();return {playAll:()=>play(true)};
}
